insert into public.clinical_order_catalog(order_type,code,name,use_text,reference_guidance,source_url) values
('lab','HC-LAB-CBC','Complete Blood Count (CBC)','Measures red cells, white cells, platelets, hemoglobin and related indices to assess anemia, infection and other blood disorders.','Each component requires the performing laboratory’s validated units, patient-specific normal limits and critical limits.','https://medlineplus.gov/lab-tests/complete-blood-count-cbc/'),
('lab','HC-LAB-BMP','Basic Metabolic Panel (BMP)','Assesses glucose, calcium, electrolytes and kidney-related measurements.','Use the performing laboratory’s validated analyte-level ranges; a panel has no single numeric range.','https://medlineplus.gov/lab-tests/basic-metabolic-panel-bmp/'),
('lab','HC-LAB-CMP','Comprehensive Metabolic Panel (CMP)','Provides information about metabolism, liver and kidney function, proteins, glucose and electrolytes.','Use the performing laboratory’s validated analyte-level ranges; a panel has no single numeric range.','https://medlineplus.gov/lab-tests/comprehensive-metabolic-panel-cmp/'),
('lab','HC-LAB-GLU','Blood Glucose','Measures glucose to screen for, diagnose or monitor disorders affecting blood sugar.','Range depends on fasting status, specimen and patient context; configure local normal and critical limits.','https://medlineplus.gov/lab-tests/blood-glucose-test/'),
('lab','HC-LAB-A1C','Hemoglobin A1C (HbA1c)','Estimates average blood glucose over approximately the previous two to three months.','Interpretation uses percentage categories and clinical context; configure the approved facility thresholds.','https://medlineplus.gov/lab-tests/hemoglobin-a1c-hba1c-test/'),
('lab','HC-LAB-LIPID','Lipid Panel','Measures cholesterol-related lipids and triglycerides to assess cardiovascular risk.','Targets vary by analyte and cardiovascular risk; record each component and facility-approved limits.','https://medlineplus.gov/lab-tests/cholesterol-levels/'),
('lab','HC-LAB-LFT','Liver Function Tests','Measures proteins, enzymes and bilirubin used to assess liver injury and function.','Each analyte has method-specific limits; configure the performing laboratory’s ranges.','https://medlineplus.gov/lab-tests/liver-function-tests/'),
('lab','HC-LAB-TSH','Thyroid-Stimulating Hormone (TSH)','Assesses thyroid function and helps diagnose or monitor thyroid disorders.','Range varies by assay, age and pregnancy status; use the local validated interval.','https://medlineplus.gov/lab-tests/tsh-thyroid-stimulating-hormone-test/'),
('lab','HC-LAB-T4','Thyroxine (T4)','Measures thyroid hormone to evaluate thyroid function.','Total and free T4 use different units and ranges; use the local validated interval.','https://medlineplus.gov/lab-tests/thyroxine-t4-test/'),
('lab','HC-LAB-T3','Triiodothyronine (T3)','Measures T3 to help evaluate thyroid disorders.','Total and free tests differ; use the performing laboratory’s validated interval.','https://medlineplus.gov/lab-tests/triiodothyronine-t3-tests/'),
('lab','HC-LAB-CRP','C-Reactive Protein (CRP)','Measures an inflammation-associated protein to help assess inflammatory conditions.','Standard and high-sensitivity CRP are interpreted differently; configure assay-specific limits.','https://medlineplus.gov/lab-tests/c-reactive-protein-crp-test/'),
('lab','HC-LAB-ESR','Erythrocyte Sedimentation Rate (ESR)','Provides a nonspecific measure that may support evaluation of inflammation.','Ranges vary with method, age and sex; use the local validated interval.','https://medlineplus.gov/lab-tests/erythrocyte-sedimentation-rate-esr/'),
('lab','HC-LAB-PTINR','Prothrombin Time and INR (PT/INR)','Evaluates clotting and is used to monitor certain anticoagulant therapy.','Interpretation depends on indication, reagent and anticoagulant target; configure approved ranges.','https://medlineplus.gov/lab-tests/prothrombin-time-test-and-inr-ptinr/'),
('lab','HC-LAB-PTT','Partial Thromboplastin Time (PTT)','Evaluates part of the clotting system and may monitor heparin therapy.','Therapeutic and reference intervals are method- and indication-specific.','https://medlineplus.gov/lab-tests/partial-thromboplastin-time-ptt-test/'),
('lab','HC-LAB-DDIMER','D-Dimer','Measures a clot-breakdown product used with clinical assessment for thrombotic disease.','Cutoffs depend on assay, units, age strategy and clinical pathway; configure locally.','https://medlineplus.gov/lab-tests/d-dimer-test/'),
('lab','HC-LAB-TROP','Troponin','Measures a cardiac protein used to assess heart muscle injury.','Assay-specific upper reference limits and serial change rules are required; configure locally.','https://medlineplus.gov/lab-tests/troponin-test/'),
('lab','HC-LAB-BNP','BNP / NT-proBNP','Measures natriuretic peptides used in assessment of heart failure.','BNP and NT-proBNP are not interchangeable; limits vary by assay, age and renal function.','https://medlineplus.gov/lab-tests/natriuretic-peptide-tests-bnp-nt-probnp/'),
('lab','HC-LAB-CREAT','Creatinine','Assesses a waste product used in evaluating kidney function.','Interpret with age, sex, muscle mass, assay and estimated GFR; use local ranges.','https://medlineplus.gov/lab-tests/creatinine-test/'),
('lab','HC-LAB-BUN','Blood Urea Nitrogen (BUN)','Measures urea nitrogen to help evaluate kidney function and hydration-related conditions.','Use specimen-, method- and age-specific local ranges.','https://medlineplus.gov/lab-tests/bun-blood-urea-nitrogen/'),
('lab','HC-LAB-EGFR','Estimated Glomerular Filtration Rate (eGFR)','Estimates kidney filtration from creatinine and patient variables.','Report the equation and clinical categories; this is not interpreted through one universal normal band.','https://medlineplus.gov/lab-tests/glomerular-filtration-rate-gfr-test/'),
('lab','HC-LAB-ELECT','Electrolyte Panel','Measures electrolytes involved in fluid balance, acid-base status, nerves and muscles.','Each analyte needs its own validated units, normal limits and critical limits.','https://medlineplus.gov/lab-tests/electrolyte-panel/'),
('lab','HC-LAB-UA','Urinalysis','Examines physical, chemical and microscopic urine findings for urinary and systemic conditions.','Contains qualitative and quantitative components; use component-specific local interpretation.','https://medlineplus.gov/urinalysis.html'),
('lab','HC-LAB-UACR','Urine Albumin-Creatinine Ratio','Assesses urine albumin relative to creatinine for kidney damage screening and monitoring.','Interpretation uses clinical categories and collection context; configure approved thresholds.','https://medlineplus.gov/lab-tests/microalbumin-creatinine-ratio/'),
('lab','HC-LAB-UCULT','Urine Culture','Detects and identifies microorganisms in urine and may support susceptibility testing.','Culture results are organism/count/susceptibility based rather than a universal numeric range.','https://medlineplus.gov/lab-tests/bacteria-culture-test/'),
('lab','HC-LAB-BCULT','Blood Culture','Detects microorganisms in blood to support diagnosis of bloodstream infection.','Report organism identification and susceptibility; no universal numeric normal range applies.','https://medlineplus.gov/lab-tests/bacteria-culture-test/'),
('lab','HC-LAB-HIV','HIV Screening','Detects markers of HIV infection as part of a validated diagnostic algorithm.','Use the assay’s reactive/nonreactive criteria and required confirmatory algorithm.','https://medlineplus.gov/lab-tests/hiv-screening-test/'),
('lab','HC-LAB-HEP','Hepatitis Panel','Detects hepatitis-related antigens or antibodies to assess infection or immunity.','Each marker is interpreted separately and in combination; no single panel range applies.','https://medlineplus.gov/lab-tests/hepatitis-testing/'),
('lab','HC-LAB-PREG','Pregnancy Test','Detects human chorionic gonadotropin in urine or blood.','Interpret using assay-specific qualitative cutoffs or quantitative gestational context.','https://medlineplus.gov/lab-tests/pregnancy-test/'),
('lab','HC-LAB-PSA','Prostate-Specific Antigen (PSA)','Measures PSA to support prostate assessment and longitudinal monitoring.','Interpretation depends on age, trend, clinical context and laboratory method.','https://medlineplus.gov/lab-tests/prostate-specific-antigen-psa-test/'),
('lab','HC-LAB-FERR','Ferritin','Measures an iron-storage protein to help assess iron status and related disorders.','Ranges vary by method, age and sex and ferritin may change with inflammation.','https://medlineplus.gov/lab-tests/ferritin-blood-test/'),
('lab','HC-LAB-IRON','Iron Studies','Measures iron-related analytes to evaluate iron deficiency or overload.','Each component requires its own method-specific interval and clinical interpretation.','https://medlineplus.gov/lab-tests/iron-tests/'),
('lab','HC-LAB-B12','Vitamin B12','Assesses vitamin B status in evaluation of deficiency and related conditions.','Use assay-specific local intervals and clinical context.','https://medlineplus.gov/lab-tests/vitamin-b-test/'),
('lab','HC-LAB-VITD','Vitamin D','Measures vitamin D status for assessment of deficiency or excess.','Decision thresholds vary by guideline and assay; configure the facility-approved standard.','https://medlineplus.gov/lab-tests/vitamin-d-test/'),
('lab','HC-LAB-ABG','Arterial Blood Gas (ABG)','Measures oxygen, carbon dioxide and acid-base variables in arterial blood.','Ranges depend on altitude, oxygen therapy, temperature and analyzer; configure analyte-specific critical limits.','https://medlineplus.gov/lab-tests/arterial-blood-gas-abg-test/'),
('lab','HC-LAB-LACT','Lactate','Measures lactate to assess impaired oxygen delivery, metabolism and treatment response.','Specimen handling and method affect results; use local normal and critical limits.','https://medlineplus.gov/lab-tests/lactate-test/'),
('imaging','CT','CT scan','Uses X-ray equipment and computers to create cross-sectional internal images.','Imaging is interpreted through radiologist findings and impression; no laboratory-style numeric normal range applies.','https://stanfordhealthcare.org/medical-clinics/imaging-clinic/types-modalities.html'),
('imaging','LDCT-LUNG','Low-dose CT lung cancer screening','Uses low-dose chest CT to screen eligible patients for lung cancer.','Report standardized findings and follow-up category under the facility’s approved protocol.','https://stanfordhealthcare.org/medical-clinics/imaging-clinic/types-modalities.html'),
('imaging','CT-COLON','CT virtual colonoscopy','Creates two- and three-dimensional views of the colon using CT and computer processing.','Report preparation quality, findings, measurements and radiologist impression.','https://stanfordhealthcare.org/medical-clinics/imaging-clinic/types-modalities.html'),
('imaging','MRI','Magnetic Resonance Imaging (MRI)','Uses a strong magnet, radiofrequency signals and computing to image internal structures.','Report findings and impression; numeric normal/critical laboratory ranges do not apply.','https://stanfordhealthcare.org/medical-clinics/imaging-clinic/types-modalities.html'),
('imaging','XR','X-ray / Radiograph','Uses ionizing radiation to create images, commonly of bones, chest and other structures.','Report technique, findings and radiologist impression; no laboratory-style range applies.','https://stanfordhealthcare.org/medical-clinics/imaging-clinic/types-modalities.html'),
('imaging','FLUORO','Fluoroscopy','Uses a continuous X-ray beam to visualize structures and motion in real time.','Report procedure details and findings; dose and measurements use protocol-specific limits.','https://stanfordhealthcare.org/medical-clinics/imaging-clinic/types-modalities.html'),
('imaging','US','Ultrasound','Uses high-frequency sound waves to create images of tissues, organs and blood vessels.','Report measurements against anatomy-, age-, sex- and pregnancy-specific standards when applicable.','https://stanfordhealthcare.org/medical-clinics/imaging-clinic/types-modalities.html'),
('imaging','DOPPLER','Doppler Ultrasound','Evaluates blood flow using ultrasound.','Velocity and index interpretation is vessel-, protocol- and patient-specific.','https://medlineplus.gov/lab-tests/doppler-ultrasound/'),
('imaging','MAMMO','Digital Mammography','Uses low-dose X-rays to screen for or diagnose breast disease.','Report findings using the facility’s approved structured breast-imaging assessment system.','https://stanfordhealthcare.org/medical-clinics/imaging-clinic/types-modalities.html'),
('imaging','TOMO','Breast Tomosynthesis','Uses low-dose X-rays to create layered breast images.','Report findings using the facility’s approved structured breast-imaging assessment system.','https://stanfordhealthcare.org/medical-clinics/imaging-clinic/types-modalities.html'),
('imaging','PET','PET scan','Uses a radiotracer and imaging system to show metabolic or biochemical activity.','Uptake values require tracer-, timing-, scanner- and protocol-specific interpretation.','https://medlineplus.gov/lab-tests/pet-scan/'),
('imaging','VQ','Ventilation/Perfusion (V/Q) scan','Uses nuclear medicine imaging to compare lung ventilation and perfusion.','Report probability or findings under the facility’s approved interpretive protocol.','https://medlineplus.gov/lab-tests/vq-scan/'),
('imaging','DEXA','Bone Density Scan (DXA/DEXA)','Uses low-dose X-rays to assess bone mineral density.','Interpret T-score or Z-score according to patient group and approved clinical standard.','https://medlineplus.gov/lab-tests/bone-density-scan/'),
('imaging','ECHO','Echocardiography','Uses ultrasound to assess heart structure and function.','Measurements require age/body-size/method-specific reference values and clinician interpretation.','https://medlineplus.gov/lab-tests/echocardiography/'),
('imaging','ELAST','Elastography','Uses imaging to assess tissue stiffness, often in the liver.','Thresholds are modality-, manufacturer- and disease-context specific.','https://medlineplus.gov/lab-tests/elastography/'),
('imaging','IVP','Intravenous Pyelogram','Uses contrast X-rays to visualize the kidneys, ureters and bladder.','Report anatomy, contrast passage and findings; no universal numeric range applies.','https://medlineplus.gov/lab-tests/intravenous-pyelogram-ivp/'),
('imaging','MYELO','Myelography','Uses contrast and imaging to evaluate the spinal canal and related structures.','Report technical details, findings and impression; no laboratory-style range applies.','https://medlineplus.gov/lab-tests/myelography/')
