-- Source-backed order catalog. Numeric reference limits are intentionally kept
-- in lab_reference_ranges because the performing laboratory must validate them.
create table if not exists public.clinical_order_catalog (
  id bigint generated by default as identity primary key,
  order_type text not null check(order_type in ('lab','imaging','procedure')),
  code text not null,
  name text not null,
  use_text text not null,
  reference_guidance text not null,
  source_url text,
  active boolean not null default true,
  unique(order_type,code)
);

alter table public.clinical_order_catalog enable row level security;
drop policy if exists clinical_order_catalog_read on public.clinical_order_catalog;
create policy clinical_order_catalog_read on public.clinical_order_catalog for select to authenticated using(active);
grant select on public.clinical_order_catalog to authenticated;

on conflict(order_type,code) do update set name=excluded.name,use_text=excluded.use_text,reference_guidance=excluded.reference_guidance,source_url=excluded.source_url,active=true;

create index if not exists clinical_order_catalog_type_name_idx on public.clinical_order_catalog(order_type,name);
